parameters.query:
SELECT DISTINCT cve_id
FROM telemetria_vulnerabilidades
ORDER BY cve_id;

parameters.jsCode:
const filas = [];

for (const item of $input.all()) {
  const registro = item.json.data?.[0];
  if (!registro) continue;

  const cve = registro.cve;

  // El dia de la corrida viene en la raiz del registro, no dentro de time-series.
  // Omitirlo perderia un dia por CVE en cada captura.
  filas.push({
    cve_id: cve,
    fecha: registro.date,
    epss_score: parseFloat(registro.epss),
    epss_percentil: parseFloat(registro.percentile)
  });

  for (const dia of registro['time-series'] ?? []) {
    filas.push({
      cve_id: cve,
      fecha: dia.date,
      epss_score: parseFloat(dia.epss),
      epss_percentil: parseFloat(dia.percentile)
    });
  }
}

return filas.map(f => ({ json: f }));

