VALUES ($1, $2::date, $3::numeric, $4::numeric)
ON CONFLICT (cve_id, fecha) DO NOTHING;

SELECT DISTINCT cve_id
FROM telemetria_vulnerabilidades
ORDER BY cve_id;

parameters.jsCode:
const filas = [];

for (const item of $input.all()) {
  const vuln = item.json.vulnerabilities?.[0]?.cve;
  if (!vuln) continue;

  const m = vuln.metrics ?? {};

  // Misma cascada que el flujo congelado (nodo Parse NVD Response): V31, V30,
  // V40 y V2, en ese orden, y cero como respaldo final. Primer elemento del
  // arreglo, sin preferir la fuente Primary. Si una punta usara una cascada
  // distinta de la otra, la diferencia contra irc_score mezclaria maduracion
  // del dato con cambio de criterio de medicion.
  const cvss = m.cvssMetricV31?.[0]?.cvssData?.baseScore
            ?? m.cvssMetricV30?.[0]?.cvssData?.baseScore
            ?? m.cvssMetricV40?.[0]?.cvssData?.baseScore
            ?? m.cvssMetricV2?.[0]?.cvssData?.baseScore
            ?? 0;

  // SSVC y la fecha de ingreso al catalogo KEV siguen admitiendo null: son
  // texto y fecha, no entran al calculo del IRC, y ahi el nulo es correcto.
  const opciones = m.ssvcV203?.[0]?.ssvcData?.options ?? [];
  const ssvc = opciones.find(o => 'exploitation' in o)?.exploitation ?? null;

  filas.push({
    cve_id:                  vuln.id,
    cvss_score_final:        cvss,
    ssvc_exploitation_final: ssvc,
    kev_status_final:        Boolean(vuln.cisaExploitAdd),
    kev_fecha_agregado:      vuln.cisaExploitAdd ? vuln.cisaExploitAdd.slice(0, 10) : null
  });
}

return filas.map(f => ({ json: f }));
